#include "Historia.h"


void DibujarMenu() {

    for (int f = 0; f < FILAS; f++) {
        for (int c = 0; c < COLUMNAS; c++) {
            Console::SetCursorPosition(c, f);
            SetColorPorValor(FondoMenu[f][c]);
            cout << "█";
        }
    }
}


int main()
{

    PlaySound(TEXT("musica\\Frances.wav"), NULL, SND_FILENAME | SND_ASYNC | SND_LOOP);
    Console::BackgroundColor = ConsoleColor::Gray;
    SetConsoleOutputCP(65001);
    Console::CursorVisible = false;

    srand(time(nullptr));


    Remy* ObjRemy = new Remy(50, 10);
    Linguini* ObjLinguini = new Linguini(80, 0);
    Skinner* ObjSkinner = new Skinner(80, 8);
    Historia* ObjHistoria = new Historia(ObjRemy, ObjLinguini, ObjSkinner);

    DibujarMenu();



    char opcion;
    int Menu{ 0 };

    while (Menu == 0) {
        opcion = (char)_getch();


        if (opcion == '1') { Beep(600, 120); Menu = 1; }
        else if (opcion == '2')
        {
            Beep(600, 120);
            ObjHistoria->Creditos();


            do
            {
                opcion = (char)_getch();
            } while (opcion != 27);

            Console::BackgroundColor = ConsoleColor::Gray;
            DibujarMenu();
            Menu = 0;
        }
        else if (opcion == '3') { Beep(400, 150); exit(0); }

    }


    // Nivel 1 

    PlaySound(NULL, NULL, 0);
    PlaySound(TEXT("musica\\Remmy.wav"), NULL, SND_FILENAME | SND_ASYNC | SND_LOOP);

    ObjHistoria->MostrarPerspectiva(1);


    ObjHistoria->EscenaInicioLinguini();

    Nivel1 nivel1(ObjRemy, ObjLinguini, ObjSkinner);


    ObjHistoria->IntroNivel1();
    nivel1.Jugar();

    ObjHistoria->EscenaNivel1(nivel1.GetCompletadoSatisfactoriamente());


    // Nivel 2
    PlaySound(NULL, NULL, 0);
    PlaySound(TEXT("musica\\Linguini.wav"), NULL, SND_FILENAME | SND_ASYNC | SND_LOOP);

    ObjHistoria->MostrarPerspectiva(2);
    ObjHistoria->IntroNivel2();

    Nivel2* ObjNivel2 = new Nivel2(ObjLinguini);
    ObjNivel2->jugar();


    ObjHistoria->EscenaNivel2(ObjNivel2->getComidasQuemadas());

    delete ObjNivel2;

    
    // Nivel 3
    PlaySound(NULL, NULL, 0);
    PlaySound(TEXT("musica\\Skinner.wav"), NULL, SND_FILENAME | SND_ASYNC | SND_LOOP);

    ObjHistoria->MostrarPerspectiva(3);
    ObjHistoria->IntroNivel3();

    Nivel3* ObjNivel3 = new Nivel3(ObjRemy, ObjLinguini, ObjSkinner);
    ObjNivel3->Jugar();

    // motivos de derrotas              0 = victoria            1 = sin vidas           2 = inspector           3 = Gusteau pero sin empatia
    int motivo = 0;

    if (!ObjNivel3->SobrevivioRondas())
    {
        motivo = 1;
    }
    else
    {

        char decision = ObjHistoria->DecisionSkinner();
        ObjNivel3->Resolver(decision);

        if (decision == 'A')
        {
            motivo = 2;
        }
        else if (!ObjNivel3->GetCompletadoSatisfactoriamente())
        {
            motivo = 3;
        }
    }

    if (motivo != 0)
    {

        ObjHistoria->PantallaPerdiste(motivo);

        delete ObjNivel3;
        delete ObjHistoria;
        delete ObjRemy;
        delete ObjLinguini;
        delete ObjSkinner;

        return 0;
    }

    ObjHistoria->EscenaNivel3(true);

    delete ObjNivel3;



    ObjHistoria->CriticaFinal();


    ObjHistoria->ReflexionFinal();

    delete ObjHistoria;
    delete ObjRemy;
    delete ObjLinguini;
    delete ObjSkinner;

    return 0;
}